{
  "status": "SUPPORTED",
  "task_summary": "Identify fastening components, perform fastening, and place tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "FastenerPart",
        "entity_kind": "OBJECT",
        "function": "Provides the mechanical connection for the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
      "candidate_categories": ["screw", "bolt", "nut", "connector"],
      "required_properties": ["compatible with workpiece", "drivable"]
      },
      {
        "id": "FasteningTool",
        "entity_kind": "OBJECT",
        "function": "Applies force to secure the connection.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
      "candidate_categories": ["screwdriver", "wrench", "driver"],
      "required_properties": ["drives fastener"]
      },
      {
        "id": "Workpiece",
        "entity_kind": "OBJECT",
        "function": "Receives the mechanical connection.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
      "candidate_categories": ["fixture", "panel", "object"],
      "required_properties": ["has fastening point"]
      },
      {
        "id": "WorkbenchSurface",
        "entity_kind": "REGION",
        "function": "Holds the workpiece and serves as a drop zone for tools.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["table top", "desk surface"],
      "required_properties": ["flat surface", "accessible"]
      }
    ],
    "functional_relations": [
      {
        "id": "FastenerConnectsToWorkpiece",
        "relation": "The FastenerPart connects to the Workpiece.",
        "participant_roles": [
          "FastenerPart",
          "Workpiece"
        ]
      ,
      "required": true
      },
      {
        "id": "ToolOperatesOnFastener",
        "relation": "The FasteningTool operates on the FastenerPart.",
        "participant_roles": [
          "FasteningTool",
          "FastenerPart"
        ]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "LocateFastener",
        "operation": "Identify and retrieve the necessary components.",
        "participant_roles": [
          "FastenerPart",
          "FasteningTool"
        ]
      ,
      "operation_count": 1
      },
      {
        "id": "PerformFastening",
        "operation": "Drive the fastener into the workpiece.",
        "participant_roles": [
          "FasteningTool",
          "FastenerPart",
          "Workpiece"
        ]
      ,
      "operation_count": 1
      },
      {
        "id": "PlaceTool",
        "operation": "Deposit the tool on the workbench surface.",
        "participant_roles": [
          "FasteningTool",
          "WorkbenchSurface"
        ]
      ,
      "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "FastenerPart": [
        {
          "label": "Items in black tray",
          "visual_description": "Small yellow and blue components inside a black tray on the table."
        }
      ],
      "FasteningTool": [
        {
          "label": "Handle in tray",
          "visual_description": "Yellow handle of a tool inside the black tray."
        },
        {
          "label": "Object in robot hand",
          "visual_description": "Yellow blocky object held by the robot arm in the third view."
        }
      ],
      "Workpiece": [
        {
          "label": "Black tray",
          "visual_description": "The black tray sitting on the table surface."
        }
      ],
      "WorkbenchSurface": [
        {
          "label": "Table top",
          "visual_description": "The wooden surface of the desk."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "CabinetDoor",
        "label": "Blue Cabinet Door",
        "visual_description": "Closed dark blue cabinet behind the table.",
        "reason": "Closed storage structure, may contain spare parts or tools."
      },
      {
        "id": "Drawers",
        "label": "Desk Drawers",
        "visual_description": "Two blue drawers under the table.",
        "reason": "Closed storage structures, may contain tools or components."
      }
    ],
    "inspection_order": [
      "CabinetDoor",
      "Drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
  }
